# >>> CHOICES
_choice_archive_args() {
    cat <<'EOF'
-c	Create a new archive
-u	Add or update files with changed mtime
-i	Like -u but always add even if unchanged
-r	Remove files from archive
-t	List contents of archive
-x	Extract files from archive
-v	Print each filename as it is processed
-f	Use archive FILE (default is current db)
-a	Open FILE using the apndvfs VFS
-C	Read/extract files from directory DIR
-g	Use glob matching for names in archive
-n	Show the SQL that would have occurred
EOF
}

_choice_cmdline_edit() {
    printf '%s\n' \
        'on	Enable command-line editing' \
        'off	Disable command-line editing'
}

_choice_dot_command() {
    sqlite3 -noinit :memory: '.help' 2>/dev/null |
        awk 'match($0, /^\.[a-z0-9]+/) {
                 cmd = substr($0, 1, RLENGTH)
                 desc = substr($0, RLENGTH + 1)
                 sub(/^[ \t]+/, "", desc)
                 if (match(desc, /[ \t]{2,}/)) desc = substr(desc, RSTART + RLENGTH)
                 sub(/[ \t]+$/, "", desc)
                 print cmd "\t" desc
             }'
}

_choice_vfs() {
    sqlite3 -noinit :memory: '.vfslist' 2>/dev/null |
        sed -n 's/^vfs\.zName[[:space:]]*=[[:space:]]*"\([^"]*\)".*/\1/p' |
        awk '!seen[$0]++'
}
# <<< CHOICES

command eval "$(argc --argc-eval "$0" "$@")"
